import { computed, defineComponent, h, inject, onBeforeUnmount, onMounted, onUpdated, provide, ref, useId, type ComputedRef, type InjectionKey, type PropType } from 'vue';
import { getTabsListVariantKey, getTabsState, observeTabsIndicator, tabsStyleKeys } from '../lib/core';
import type { TabsListVariant, TabsOrientation } from '../lib/core';
import styles from './tabs.module.scss';

interface TabsContextValue {
	value: string;
	orientation: TabsOrientation;
	baseId: string;
	select: (value: string) => void;
}

type TabsContext = ComputedRef<TabsContextValue>;

const TabsContextKey: InjectionKey<TabsContext> = Symbol('tile-tabs');

export const Tabs = defineComponent({
	name: 'Tabs',
	props: {
		modelValue: { type: String, default: undefined },
		defaultValue: { type: String, default: '' },
		orientation: {
			type: String as PropType<TabsOrientation>,
			default: 'horizontal',
		},
	},
	emits: ['update:modelValue', 'change'],
	setup(props, { emit, slots }) {
		const internalValue = ref(props.defaultValue);
		const currentValue = computed(() => (props.modelValue !== undefined ? props.modelValue : internalValue.value));
		const baseId = useId();

		const context = computed<TabsContextValue>(() => ({
			value: currentValue.value,
			orientation: props.orientation,
			baseId,
			select: (next: string) => {
				if (props.modelValue === undefined) {
					internalValue.value = next;
				}
				emit('update:modelValue', next);
				emit('change', next);
			},
		}));

		provide(TabsContextKey, context);

		return () => h('div', { class: styles[tabsStyleKeys.root], 'data-orientation': props.orientation }, slots.default?.());
	},
});

export const TabsList = defineComponent({
	name: 'TabsList',
	props: {
		variant: {
			type: String as PropType<TabsListVariant>,
			default: 'default',
		},
	},
	setup(props, { slots }) {
		const context = inject(TabsContextKey);
		if (!context) {
			throw new Error('TabsList must be used within <Tabs>.');
		}

		const variantKey = computed(() => getTabsListVariantKey(props.variant));
		const isVertical = computed(() => context!.value.orientation === 'vertical');
		const listRef = ref<HTMLDivElement>();
		const indicatorRef = ref<HTMLSpanElement>();
		let measurement: ReturnType<typeof observeTabsIndicator> | undefined;
		onMounted(() => {
			if (listRef.value && indicatorRef.value) measurement = observeTabsIndicator(listRef.value, indicatorRef.value);
		});
		onUpdated(() => measurement?.update());
		onBeforeUnmount(() => measurement?.disconnect());

		function handleKeydown(event: KeyboardEvent) {
			const nextKey = isVertical.value ? 'ArrowDown' : 'ArrowRight';
			const prevKey = isVertical.value ? 'ArrowUp' : 'ArrowLeft';
			const isNext = event.key === nextKey;
			const isPrev = event.key === prevKey;
			const isHome = event.key === 'Home';
			const isEnd = event.key === 'End';

			if (!isNext && !isPrev && !isHome && !isEnd) {
				return;
			}

			const triggers = Array.from((event.currentTarget as HTMLElement).querySelectorAll<HTMLButtonElement>('button[role="tab"]')).filter((trigger) => !trigger.disabled);

			if (triggers.length === 0) {
				return;
			}

			const currentIndex = triggers.indexOf(document.activeElement as HTMLButtonElement);
			let nextIndex: number;
			if (isHome) {
				nextIndex = 0;
			} else if (isEnd) {
				nextIndex = triggers.length - 1;
			} else {
				const direction = isNext ? 1 : -1;
				nextIndex = (currentIndex + direction + triggers.length) % triggers.length;
			}

			const nextTrigger = triggers[nextIndex];
			nextTrigger?.focus();

			const nextValue = nextTrigger?.getAttribute('data-value');
			if (nextValue !== null && nextValue !== undefined) {
				context!.value.select(nextValue);
			}

			event.preventDefault();
		}

		return () =>
			h(
				'div',
				{
					ref: listRef,
					class: [styles[tabsStyleKeys.list], styles[variantKey.value]],
					role: 'tablist',
					'data-orientation': context.value.orientation,
					'data-variant': props.variant,
					onKeydown: handleKeydown,
				},
				[slots.default?.(), h('span', { ref: indicatorRef, 'aria-hidden': 'true', 'data-slot': 'tabs-indicator', 'data-state': 'hidden', class: styles.indicator })],
			);
	},
});

export const TabsTrigger = defineComponent({
	name: 'TabsTrigger',
	props: {
		value: { type: String, required: true },
		disabled: { type: Boolean, default: false },
	},
	setup(props, { slots }) {
		const context = inject(TabsContextKey);
		if (!context) {
			throw new Error('TabsTrigger must be used within <Tabs>.');
		}

		const active = computed(() => context.value.value === props.value);
		const state = computed(() => getTabsState(active.value));
		const triggerId = computed(() => `${context.value.baseId}-trigger-${props.value}`);
		const contentId = computed(() => `${context.value.baseId}-content-${props.value}`);

		return () =>
			h(
				'button',
				{
					type: 'button',
					id: triggerId.value,
					role: 'tab',
					'aria-selected': active.value,
					'aria-controls': contentId.value,
					'data-value': props.value,
					tabindex: active.value ? 0 : -1,
					disabled: props.disabled,
					'data-state': state.value,
					'data-orientation': context.value.orientation,
					class: styles[tabsStyleKeys.trigger],
					onClick: () => context.value.select(props.value),
				},
				slots.default?.(),
			);
	},
});

export const TabsContent = defineComponent({
	name: 'TabsContent',
	props: {
		value: { type: String, required: true },
	},
	setup(props, { slots }) {
		const context = inject(TabsContextKey);
		if (!context) {
			throw new Error('TabsContent must be used within <Tabs>.');
		}

		const active = computed(() => context.value.value === props.value);
		const state = computed(() => getTabsState(active.value));
		const contentId = computed(() => `${context.value.baseId}-content-${props.value}`);
		const triggerId = computed(() => `${context.value.baseId}-trigger-${props.value}`);

		return () =>
			h(
				'div',
				{
					id: contentId.value,
					role: 'tabpanel',
					'aria-labelledby': triggerId.value,
					'data-state': state.value,
					'data-orientation': context.value.orientation,
					hidden: !active.value,
					class: styles[tabsStyleKeys.content],
				},
				slots.default?.(),
			);
	},
});

export default Tabs;

@use '../../../styles/variables/colors' as *;

.root {
	display: flex;
	gap: var(--tile-tabs-gap, $spacing-2);
	font-weight: var(--tile-tabs-root-font-weight, inherit);

	&[data-orientation='horizontal'] {
		flex-direction: column;
	}

	&[data-orientation='vertical'] {
		flex-direction: row;
	}
}

.list {
	position: var(--tile-tabs-list-position, static);
	isolation: var(--tile-tabs-list-isolation, auto);
	display: inline-flex;
	width: fit-content;
	align-items: var(--tile-tabs-list-align, center);
	justify-content: center;
	border-radius: var(--tile-tabs-list-radius, $radius-lg);
	padding: var(--tile-tabs-list-padding, 3px);
	background-color: var(--tile-tabs-list-background, $muted);
	color: var(--tile-tabs-list-foreground, var(--tile-tabs-foreground, $muted-foreground));
	box-shadow: var(--tile-tabs-list-shadow, none);
	transition: background-color $transition-fast;
	outline: none;

	&::before {
		content: var(--tile-tabs-track-ring-content, none);
		position: absolute;
		inset: 0;
		border-radius: inherit;
		box-shadow: var(--tile-tabs-track-ring-shadow, none);
		pointer-events: none;
	}

	&:focus-visible {
		box-shadow: var(--tile-tabs-focus-shadow, 0 0 0 2px $background, 0 0 0 4px $ring);
	}

	&[data-orientation='horizontal'] {
		height: var(--tile-tabs-list-height, 2.25rem);
	}

	&[data-orientation='vertical'] {
		height: fit-content;
		flex-direction: column;
	}

	// 变体
	&.variantLine {
		gap: var(--tile-tabs-line-gap, $spacing-1);
		background-color: transparent;
		border-radius: 0;
		padding: var(--tile-tabs-line-padding, 3px);
		box-shadow: var(--tile-tabs-line-shadow, none);
		border-bottom: var(--tile-tabs-line-border-bottom, 0 solid transparent);
		border-color: var(--tile-tabs-line-border-color, currentcolor);

		&::before {
			content: none;
		}

		&[data-orientation='horizontal'] {
			height: var(--tile-tabs-line-height, 2.25rem);
		}

		> .trigger[data-state='active'] {
			background-color: transparent;
			box-shadow: none;

			&::after {
				display: var(--tile-tabs-active-pseudo-display, block);
				content: '';
				position: absolute;
				background-color: var(--tile-tabs-line-color, $foreground);
			}
		}

		&[data-orientation='horizontal'] > .trigger[data-state='active']::after {
			left: 0;
			right: 0;
			bottom: -5px;
			height: 2px;
		}

		&[data-orientation='vertical'] > .trigger[data-state='active']::after {
			top: 0;
			bottom: 0;
			right: -4px;
			width: 2px;
		}
	}
}

.trigger {
	position: relative;
	z-index: var(--tile-tabs-trigger-z-index, auto);
	display: inline-flex;
	flex: var(--tile-tabs-trigger-flex, 1);
	align-items: center;
	justify-content: center;
	gap: $spacing-1_5;
	border: var(--tile-tabs-trigger-border-width, 1px) solid transparent;
	border-radius: var(--tile-tabs-trigger-radius, $radius-md);
	padding: var(--tile-tabs-trigger-padding, $spacing-1 $spacing-2);
	margin: var(--tile-tabs-trigger-margin, 0);
	font-size: var(--tile-tabs-font-size, $text-sm);
	font-weight: var(--tile-tabs-font-weight, $font-medium);
	white-space: nowrap;
	color: var(--tile-tabs-foreground, $muted-foreground);
	transition:
		color $transition-fast,
		box-shadow $transition-fast;
	outline: none;
	user-select: none;

	&:hover {
		color: var(--tile-tabs-active-foreground, $foreground);
	}

	&:focus-visible {
		border-color: var(--tile-tabs-focus-border, $ring);
		box-shadow: var(--tile-tabs-trigger-focus-shadow, 0 0 0 3px color-mix(in srgb, $ring 50%, transparent));
	}

	&:disabled {
		pointer-events: none;
		opacity: 0.5;
	}

	&[data-state='active'] {
		background-color: var(--tile-tabs-active-background, $background);
		color: var(--tile-tabs-active-foreground, $foreground);
		box-shadow: var(--tile-tabs-active-shadow, $shadow-sm);
	}

	&[data-orientation='vertical'] {
		width: 100%;
		justify-content: flex-start;
	}

	svg {
		pointer-events: none;
		width: 1rem;
		height: 1rem;
		flex-shrink: 0;
	}
}

.content {
	flex: 1;
	border-radius: var(--tile-tabs-content-radius, $radius);
	outline: none;

	&:focus-visible {
		box-shadow: var(--tile-tabs-trigger-focus-shadow, 0 0 0 3px color-mix(in srgb, $ring 50%, transparent));
	}
}

// One independent indicator per list. It is inert in the original Tile theme.
.indicator {
	display: var(--tile-tabs-indicator-display, none);
	position: absolute;
	pointer-events: none;
	z-index: 0;
	left: 0;
	top: 0;
	width: var(--tile-tabs-indicator-width, 0px);
	height: var(--tile-tabs-indicator-height, 0px);
	transform: translate(var(--tile-tabs-indicator-left, 0px), var(--tile-tabs-indicator-top, 0px));
	border-radius: var(--tile-tabs-indicator-radius, $radius-md);
	background-color: var(--tile-tabs-indicator-background, $background);
	box-shadow: var(--tile-tabs-indicator-shadow, $shadow-sm);
	transition:
		transform 200ms ease,
		width 200ms ease,
		height 200ms ease;

	&[data-state='hidden'] {
		visibility: hidden;
	}
}

.variantLine {
	> .trigger {
		padding: var(--tile-tabs-line-trigger-padding, $spacing-1 $spacing-2);
		margin: var(--tile-tabs-line-trigger-margin, 0);
		border-radius: var(--tile-tabs-line-trigger-radius, $radius-md);

		&:hover {
			background-color: var(--tile-tabs-line-hover-background, transparent);
		}
	}

	&[data-orientation='horizontal'] > .indicator {
		top: auto;
		bottom: 0;
		height: 2px;
		transform: translateX(var(--tile-tabs-indicator-left, 0px));
		border-radius: 0;
		background-color: var(--tile-tabs-line-color, $foreground);
		box-shadow: none;
	}

	&[data-orientation='vertical'] > .indicator {
		left: auto;
		inset-inline-end: 0;
		width: 2px;
		transform: translateY(var(--tile-tabs-indicator-top, 0px));
		border-radius: 0;
		background-color: var(--tile-tabs-line-color, $foreground);
		box-shadow: none;
	}
}

// Selected-state shadows otherwise override keyboard focus, especially in line lists.
.trigger[data-state='active']:focus-visible {
	box-shadow: var(--tile-tabs-trigger-focus-shadow, var(--tile-tabs-active-shadow, $shadow-sm));
}

.list.variantLine > .trigger[data-state='active']:focus-visible {
	box-shadow: var(--tile-tabs-trigger-focus-shadow, none);
}

@media (prefers-reduced-motion: reduce) {
	.indicator {
		transition: none;
	}
}
